#!/usr/bin/env bash\nset -e\n\n# Mock rationale: Use a temporary directory to avoid touching real SSH keys\nTMP_DIR=$(mktemp -d)\nKEY_PATH="$TMP_DIR/ssh_host_rsa_key"\nBACKUP_DIR="$TMP_DIR/backup_keys"\n\n# Create a dummy existing key to test backup functionality\nssh-keygen -t rsa -b 4096 -f "$KEY_PATH" -N "" > /dev/null\n\n# Run the playbook; it should backup the existing key and (re)generate it\nansible-playbook -i inventory.ini rotate_ssh_key.yml \
  -e "key_path=$KEY_PATH backup_dir=$BACKUP_DIR target=localhost" \
  --connection=local\n\n# Verify that the new key file exists\nif [ -f "$KEY_PATH" ]; then\n  echo "New SSH key exists."\nelse\n  echo "SSH key missing."\n  exit 1\nfi\n\n# Verify that a backup was created\nif ls "$BACKUP_DIR"/ssh_host_rsa_key_* 1> /dev/null 2>&1; then\n  echo "Backup created."\nelse\n  echo "Backup not found."\n  exit 1\nfi\n\n# Clean up temporary files\nrm -rf "$TMP_DIR"\n\necho "Test passed."\nexit 0
